"use client";
import {useResource,Table,Notice,Badge,date} from "@/components/BillingUI";
interface Payment{id:number;reference:string;method:string;amount:number;status:string;phone:string;voucher:string;packageName:string;router:string;createdAt:string;notes:string}
export default function Page(){const {data,loading,error}=useResource<Payment>("/api/finance/payments",true);return <div className="mx-auto max-w-7xl space-y-6"><h1 className="text-2xl font-semibold text-slate-900">Payments</h1><p className="text-sm text-slate-500">Online payments and manually recorded walk-in or binding sales.</p><Notice text={error}/><Table rows={data} loading={loading} columns={[{label:"Reference",render:p=>p.reference},{label:"Method",render:p=>p.method},{label:"Amount",render:p=>`UGX ${Number(p.amount).toLocaleString()}`},{label:"Status",render:p=><Badge tone={p.status==="SUCCESSFUL"?"green":"amber"}>{p.status}</Badge>},{label:"Phone",render:p=>p.phone},{label:"Voucher",render:p=>p.voucher||"—"},{label:"Package",render:p=>p.packageName},{label:"Router",render:p=>p.router},{label:"Recorded",render:p=>date(p.createdAt)},{label:"Notes",render:p=>p.notes||"—"}]}/></div>;}
